with a as(select * from public.authors where open_library_id=any(array['OL7634169A','OL10830350A','OL9552944A']::text[])),w as(select * from public.works where open_library_id=any(array['OL33892335W','OL29299371W','OL24338803W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9789022576229','9789026346897','9789463821049']::text[]) or open_library_edition_id=any(array['OL45876799M','OL61238876M','OL41995844M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987162001 and 987162999),'editions',(select count(*) from public.editions where id between 987262001 and 987262999),'authors',(select count(*) from public.authors where id between 987362001 and 987362999))) as preflight;
